body .callout[data-callout*="dragon"]  {
    --callout-icon: none;
	color: var(--lw);
	background-image: var(--gdj-dragon);
	background-size: 100% auto;
	background-position: 50% 0%;
	background-repeat: repeat;
}

.nborder-dragon {
	border-style: solid;
	border-width: 10px;
	border-color: color-mix(in srgb, white, transparent 70%);
	border-image: var(--gdj-dragon) 20;
}

.nborder-dragon-layer { 
	border-style: solid;
	border-width: 1px;
	border-color: color-mix(in srgb, white, transparent 70%);
	border-image: var(--gdj-dragon);
	border-image-width: auto;
	border-image-outset: 0 0 600 0;
	border-image-repeat: repeat;
}

.nhr-dragon {
	--hr-svg: var(--gdj-dragon);
}

.nbg-stamp-dragon {
	--stamp-svg: var(--gdj-dragon);
}

.nmask-dragon {
	-webkit-mask-image: var(--gdj-dragon), radial-gradient(black 50%, color-mix(in srgb, black, transparent 65%) 70%, color-mix(in srgb, black, transparent 100%) 90%);
}
.nmask-dragon-less {
	-webkit-mask-image: var(--gdj-dragon), radial-gradient(black 50%, color-mix(in srgb, black, transparent 50%) 70%);
}
.nmask-dragon-fade {
	-webkit-mask-image: var(--gdj-dragon), linear-gradient(black 65%, transparent 90%);
}
.nmask-dragon-fademore {
	-webkit-mask-image: var(--gdj-dragon), linear-gradient(black 35%, transparent 65%);
}
.nmask-dragon-simple {
	-webkit-mask-image: var(--gdj-dragon), linear-gradient(color-mix(in srgb, black, transparent 25%) 25%, color-mix(in srgb, black, transparent 50%) 75%);
}